mapper.select:
SELECT R.RECORD_ID, R.REMINDER_ID, B.REMINDER_NAME, R.SEND_TIME, R.REMINDER_TYPE, R.TARGET_COUNT, R.SUCCESS_COUNT, R.FAILURE_COUNT, R.RESPONSE_COUNT, R.OPERATOR, R.REMARKS FROM TBL_BUDGET_REMINDER_RECORD R LEFT JOIN TBL_BUDGET_REMINDER B ON R.REMINDER_ID = B.REMINDER_ID WHERE R.DEL_FLAG = 0
AND R.REMINDER_ID = #{reminderId}
ORDER BY R.SEND_TIME DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY
